import Base

type Rs is Data:
  R0{}
  R1{}
  R2{}
  R3{}

type Ch is Data:
  End{}
  Ok{h: Rs, t: Ch}

type Flag is Data:
  Off{}
  On{}

type Shape is Data:
  A{}
  B{}
  C{x: Flag}
  D{x: Flag, y: Flag}

def dense(s: Shape) -> Rs:
  match s:
    case A{}: R0{}
    case B{}: R1{}
    case C{+x}: R2{}
    case D{+x, +y}: R3{}

def tail(s: Shape) -> Rs:
  match s:
    case A{}: R0{}
    case C{+x}: R1{}
    case _: R2{}

def head(s: Shape) -> Rs:
  match s:
    case B{}: R0{}
    case D{+x, +y}: R1{}
    case _: R2{}

def main() -> Ch:
  Ok{dense(A{}), Ok{dense(B{}), Ok{dense(C{On{}}), Ok{dense(D{Off{}, On{}}), Ok{tail(A{}), Ok{tail(B{}), Ok{tail(C{On{}}), Ok{tail(D{Off{}, On{}}), Ok{head(A{}), Ok{head(B{}), Ok{head(C{On{}}), Ok{head(D{Off{}, On{}}), End{}}}}}}}}}}}}}
